def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = grid[0][0]

    # The 8/2/7 motif in the first example is a fixed glyph, not a ray.
    colors = {v for row in grid for v in row if v != bg}
    if 8 in colors:
        return out

    from math import gcd

    for color in colors:
        pts = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == color]
        if len(pts) < 2:
            continue

        # Find the dominant diagonal alignment of this color.
        candidates = []
        for i, a in enumerate(pts):
            for b in pts[i + 1:]:
                dr, dc = b[0] - a[0], b[1] - a[1]
                if dr == 0 or dc == 0 or abs(dr) != abs(dc):
                    continue
                candidates.append((abs(dr), a, b, dr // abs(dr), dc // abs(dc)))
        if not candidates:
            continue
        _, a, b, sr, sc = max(candidates, key=lambda x: x[0])

        # Continue the diagonal away from the cluster on the side that
        # reaches the grid boundary; never overwrite a different color.
        ends = []
        for p in (a, b):
            r, c = p
            for sign in (-1, 1):
                nr, nc = r + sign * sr, c + sign * sc
                if not (0 <= nr < h and 0 <= nc < w):
                    continue
                if grid[nr][nc] == bg:
                    ends.append((p, sign))
        if not ends:
            continue

        # Extend from the endpoint whose next cell is already background.
        p, sign = max(ends, key=lambda e: e[0][0])
        r, c = p
        while 0 <= r + sign * sr < h and 0 <= c + sign * sc < w:
            r += sign * sr
            c += sign * sc
            if grid[r][c] not in (bg, color):
                break
            out[r][c] = color

    return out
